import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const r=JSON.parse('{"title":"Kanuni za Msingi za Kurudi Nyuma kwa Wakati","description":"","frontmatter":{},"headers":[],"relativePath":"sw/82-时间回溯基本原则.md","filePath":"sw/82-时间回溯基本原则.md","lastUpdated":1789183869000}'),k={name:"sw/82-时间回溯基本原则.md"};function w(o,a,m,e,h,d){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="kanuni-za-msingi-za-kurudi-nyuma-kwa-wakati" tabindex="-1">Kanuni za Msingi za Kurudi Nyuma kwa Wakati <a class="header-anchor" href="#kanuni-za-msingi-za-kurudi-nyuma-kwa-wakati" aria-label="Permalink to &quot;Kanuni za Msingi za Kurudi Nyuma kwa Wakati&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>82</td></tr><tr><td>Moduli</td><td>Mwingiliano wa Kati ya Ndege na Kanuni za Wakati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Kurudi nyuma kwa wakati, uchunguzi awali kisha kuingilia kazi kwa mdogo, utulivu wa mstari wa wakati, uhifadhi wa sababu, nanga ya nanga</td></tr></tbody></table><h2 id="_1-ufafanuzi-na-asili-ya-kurudi-nyuma-kwa-wakati" tabindex="-1">1. Ufafanuzi na Asili ya Kurudi Nyuma kwa Wakati <a class="header-anchor" href="#_1-ufafanuzi-na-asili-ya-kurudi-nyuma-kwa-wakati" aria-label="Permalink to &quot;1. Ufafanuzi na Asili ya Kurudi Nyuma kwa Wakati&quot;">​</a></h2><p>Kurudi nyuma kwa wakati inamaanisha hatua ya kutuma fahari, taarifa, au vifaa nyuma kwenye nodi ya wakati uliopita kupitia uwezo wa uendeshaji wa mwelekeo wa wakati wa mtandao wa sheria za nanga. Chini ya muundo wa sheria za Hengyuanzhou, wakati sio mtiririko wa mstari wa mwelekeo mmoja usioweza kurudishwa, bali mwelekeo unaoweza kuendeshwa ndani ya mtandao wa sheria. Walakini, uendeshaji wa mwelekeo wa wakati una hatari ya juu sana na vizuizi vya mkali; hatua yoyote ya kurudi nyuma kwa wakati inaweza kusababisha usumbufu wa mnyororo wa sababu, mgawanyiko wa mstari wa wakati, hata mzunguko wa sheria wa kiwango cha ulimwengu.</p><p>Asili ya kurudi nyuma kwa wakati ni &quot;kuunda njia ya kurudi nyuma kwenye mwelekeo wa wakati wa mtandao wa sheria, kuruhusu taarifa au nishati fulani kuenea kwa kinyume chini ya njia&quot;. Mchakato huu unahitaji utumiaji wa nishati ya nanga ya kiwango kikubwa, na kadiri wakati wa kurudi nyuma unavyokuwa mbali, na kadiri maudhui ya kurudi nyuma yanavyokuwa changamano, utumiaji wa nishati unakua kwa kasi. Kwa sasa, uwezo wa teknolojia wa Hengyuanzhou unasaidia tu kurudi nyuma kwa kiwango cha fahari na taarifa; kurudi nyuma kamili kwa kiwango cha vifaa bado iko katika hatua ya utafiti wa kinadharia.</p><p>Inahitajika kusisitizwa mahsusi kwamba kurudi nyuma kwa wakati haifanani na &quot;kusafiri kwa wakati&quot;. Mtu anayerudi nyuma haingii nyuma katika mwelekeo wa vifaa kamili, bali anafika kwenye nodi ya wakati lengwa kwa namna ya taswira ya fahari au pakiti ya taarifa. Uwepo wa mtu anayerudi nyuma wakati wa zamani ni &quot;nusu-uwazi&quot; — anaweza kuchunguza, lakini uwezo wa mwingiliano wa kimwili umefadhiwa kwa mkali. Muundo huu yenyewe ni sehemu ya mchakato wa usalama wa kurudi nyuma kwa wakati.</p><h2 id="_2-kanuni-saba-za-msingi-za-kurudi-nyuma-kwa-wakati" tabindex="-1">2. Kanuni Saba za Msingi za Kurudi Nyuma kwa Wakati <a class="header-anchor" href="#_2-kanuni-saba-za-msingi-za-kurudi-nyuma-kwa-wakati" aria-label="Permalink to &quot;2. Kanuni Saba za Msingi za Kurudi Nyuma kwa Wakati&quot;">​</a></h2><p>Uendeshaji wa kurudi nyuma kwa wakati wa Hengyuanzhou unafuata kanuni saba za msingi zifuatazo, zilizotangazwa na Baraza la Nanga kwa namna ya uamuzi maalum, zikiwa na nguvu ya kisheria ikifuatiwa tu na Katiba:</p><table tabindex="0"><thead><tr><th>Nambari ya Kanuni</th><th>Jina la Kanuni</th><th>Maudhui ya Msingi</th></tr></thead><tbody><tr><td>Kanuni ya Kwanza</td><td>Uchunguzi awali, kisha kuingilia kazi kwa mdogo</td><td>Kurudi nyuma yoyote lazima kwanza ukamilishe hatua ya uchunguzi safi, na baada ya kuhakikisha kuwa hakuna hatari kubwa ndipo inaweza kufanyika kuingilia kazi kwa mdogo</td></tr><tr><td>Kanuni ya Pili</td><td>Uhifadhi wa sababu</td><td>Hatua ya kurudi nyuma haiwezi kubadilisha mnyororo wa msingi wa sababu ambao umetokea; upotofu wa sababu unaotokana na kurudi nyuma lazima ukarabatiwe baada ya kurudi nyuma kumalizika</td></tr><tr><td>Kanuni ya Tatu</td><td>Nanga ya nanga</td><td>Uendeshaji wote wa kurudi nyuma lazima uwe na nanga thabiti kama asili ya koordinati za wakati; kurudi nyuma kwa upasifu bila nanga kunakatazwa</td></tr><tr><td>Kanuni ya Nne</td><td>Athari ndogo</td><td>Hatua zote wakati wa mchakato wa kurudi nyuma lazima zifuate kanuni ya athari ndogo, kupunguza usumbufu kwenye mstari wa wakati wa zamani kadiri iwezekanavyo</td></tr><tr><td>Kanuni ya Tano</td><td>Inayoweza kufuatiliwa</td><td>Kila mara kurudi nyuma lazima ukumbuke kumbukumbu kamili ya uendeshaji, ikiwa ni pamoja na kitambulisho cha mtu anayerudi nyuma, wakati lengwa, maudhui ya uchunguzi, hatua za kuingilia kazi, na tathmini ya upotofu wa sababu</td></tr><tr><td>Kanuni ya Sita</td><td>Kataza paradox</td><td>Uendeshaji wowote unaoweza kusababisha paradox ya wakati unakatazwa kwa mkali, ikiwa ni pamoja na lakini haiwezi kupunguzwa na paradox ya babu, paradox ya taarifa, na paradox ya ontolojia</td></tr><tr><td>Kanuni ya Saba</td><td>Ukaguzi wa baadaye</td><td>Baada ya kurudi nyuma kumalizika, lazima ufanyike ukaguzi wa baadaye na kamati ya uhakika wa sheria za wakati ya kujitegemea, ili kuhakikisha kuwa hakuna usumbufu wa mstari wa wakati ambao hauwezi kudhibitiwa</td></tr></tbody></table><p>Kati ya kanuni saba, &quot;uchunguzi awali, kisha kuingilia kazi kwa mdogo&quot; ni kanuni ya uendeshaji ya msingi zaidi, na kanuni zingine sita zote zinatokea kuzungumzia msingi huu. Kanuni za maelezo zaidi za uendeshaji za kanuni hii zinaweza kupatikana katika Hati 83 &quot;Miongozo ya Uchunguzi awali, Kisha Kuingilia Kazi kwa Mdogo&quot;.</p><h2 id="_3-usimamizi-wa-uainishaji-wa-kurudi-nyuma-kwa-wakati" tabindex="-1">3. Usimamizi wa Uainishaji wa Kurudi Nyuma kwa Wakati <a class="header-anchor" href="#_3-usimamizi-wa-uainishaji-wa-kurudi-nyuma-kwa-wakati" aria-label="Permalink to &quot;3. Usimamizi wa Uainishaji wa Kurudi Nyuma kwa Wakati&quot;">​</a></h2><p>Kulingana na upeo wa wakati wa kurudi nyuma na kiwango cha kuingilia kazi, uendeshaji wa kurudi nyuma kwa wakati umegawanywa katika viwango vitatu vya usimamizi:</p><ol><li><p><strong>Kurudi Nyuma kwa Kiwango cha 1 (Uchunguzi wa Wakati wa Karibu)</strong>: Upeo wa wakati wa kurudi nyuma hauzidi miaka 100 ya wakati wa kiwango cha ndege ya mwenyewe, na hutumiwa tu uchunguzi safi bila kuingilia kazi yoyote. Inaidhinishwa na Ofisi ya Usimamizi wa Ndege; mchakato wa uendeshaji lazima uwe na wachunguzi wawili au zaidi wa sheria za wakati walipo kwa ufuatiliaji.</p></li><li><p><strong>Kurudi Nyuma kwa Kiwango cha 2 (Uchunguzi wa Wakati wa Mbali)</strong>: Upeo wa wakati wa kurudi nyuma unazidi miaka 100 lakini hauzidi miaka 10,000, au mchakato wa kurudi nyuma unahitaji kuingilia kazi kwa mwepesi sana (kama vile kutuma taarifa moja). Lazima idhinishwe na Kamati ya Sheria za Wakati chini ya Baraza la Nanga, na lazima iandaliwe mpango wa dharura wa maelezo ya upotofu wa sababu.</p></li><li><p><strong>Kurudi Nyuma kwa Kiwango cha 3 (Kuingilia Kazi kwa Kina)</strong>: Upeo wa wakati wa kurudi nyuma unazidi miaka 10,000, au mchakato wa kurudi nyuma unahitaji kuingilia kazi kwa kweli. Lazima ipitwe na majority zaidi ya theluthi mbili katika mkutano kamili wa Baraza la Nanga, na ipitie uchunguzi wa kukataza katiba na Mahakama ya Symbiosis, ili kuhakikisha kuwa hatua ya kuingilia kazi inafuata kanuni za msingi za Katiba ya Symbiosis.</p></li></ol><p>Kurudi nyuma kwa wakati kwa kiwango chochote kunakatazwa kwa madhumuni yafuatayo: kutafuta manufaa ya kibinafsi kwa watu au vikundi vidogo, kubadilisha hatima ya watu wa kihistoria ili kutosheleza hamu ya kibinafsi, kubadilisha mchakato wa asili wa mageuzi ya ustaarabu, na aina yoyote ya uendeshaji wa &quot;urekebishaji wa kihistoria&quot;.</p><h2 id="_4-vizuizi-vya-nishati-na-teknolojia-za-kurudi-nyuma-kwa-wakati" tabindex="-1">4. Vizuizi vya Nishati na Teknolojia za Kurudi Nyuma kwa Wakati <a class="header-anchor" href="#_4-vizuizi-vya-nishati-na-teknolojia-za-kurudi-nyuma-kwa-wakati" aria-label="Permalink to &quot;4. Vizuizi vya Nishati na Teknolojia za Kurudi Nyuma kwa Wakati&quot;">​</a></h2><p>Matumizi ya nishati ya kurudi nyuma kwa wakati ni makubwa sana. Kuchukua kurudi nyuma kwa taswira ya fahari kama mfano, nishati inayohitajika kwa kurudi nyuma kwa miaka 1 ni takriban 10,000 vitengo vya nishati vya kiwango, kwa kurudi nyuma kwa miaka 100 ni takriban 1 milioni vitengo vya nishati vya kiwango, na kwa kurudi nyuma kwa miaka 10,000 inahitaji takriban 10 bilioni vitengo vya nishati vya kiwango. Matumizi ya nishati na upeo wa wakati wa kurudi nyuma yana uhusiano wa karibu wa logaritimu-mstari, lakini wakati wa kuvuka nodi za kihistoria za muhimu kutokea kilele cha nishati — hii ni kwa sababu msongamano wa mnyororo wa sababu kwenye nodi za kihistoria za muhimu ni wa juu sana, na uendeshaji wa kurudi nyuma unahitaji kuvuka uvumilivu wa sababu mkubwa zaidi.</p><p>Kwa kiwango cha teknolojia, kurudi nyuma kwa wakati inahitaji kazi ya ulinganifu kati ya &quot;kifaa cha nanga ya sheria za wakati&quot; na &quot;safu ya usambazaji wa taswira ya fahari&quot;. Ya kwanza inawajibika kwa kuunda koordinati za wakati thabiti kwenye nodi ya wakati lengwa, ya pili inawajibika kwa kufikisha taswira ya fahari ya mtu anayerudi nyuma kwa usalama na kudumisha uwepo wake wakati wa zamani. Vifaa vyote vya kurudi nyuma lazima vipitie ushahidi wa usalama wa Kamati ya Ufuatiliaji wa Nanga; kutumia vifaa vya kujifanya ambavyo havina ushahidi kwa uendeshaji wa kurudi nyuma kunakatazwa.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kurudi nyuma kwa wakati ni moja ya uwezo wa uendeshaji wa sheria wenye nguvu zaidi na hatari zaidi katika Hengyuanzhou. Kanuni saba za msingi na mfumo wa usimamizi wa uainishaji pamoja huunda muundo wa usalama wa kurudi nyuma kwa wakati, ambayo roho yake ya msingi ni &quot;heshimu sababu, uendeshaji kwa uangalifu&quot;. Matumizi ya halali ya kurudi nyuma kwa wakati ni mdogo tu katika utafiti wa kichunguzi, urejesho wa ukweli wa kihistoria, na tahadhari ya mapema ya mzozo wa kiwango cha kutoweka; matumizi yoyote ya nje ya upeo huu yatachukuliwa kuwa ucheusi kwa sheria za ulimwengu.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>83-Miongozo ya Uchunguzi awali, Kisha Kuingilia Kazi kwa Mdogo</li><li>89-Mchakato wa Kuzuia na Kudhibiti Paradox ya Wakati</li><li>84-Muhtasari wa Itifaki ya Kichunguzi</li></ul>',21)])])}const s=i(k,[["render",w]]);export{r as __pageData,s as default};
